mapper.select:
select



from  Project_Cp_Subtask pcs
left join  Project_Cp_Dtl cpd on cpd.Cpd_Id=pcs.Cpd_Id
left join  Project_Cp cp on cp.Cp_Id=cpd.Cp_Id
left join  Pre_Project pro on pro.P_ID=cp.P_ID

left join  SYS_User u on  u.U_ID=pcs.Pcs_Handler

    
        and pcs.Te_Id = #{params.teId}
    
    
        and   pcs.Cpd_Id=#{params.cpdId}
    
    
        and cp.P_ID=#{params.pId}
    
    
        
            
                and likePname(#{params.pName},cp.P_ID)=true
            
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        and  cpd.Cpd_Name like concat('%',#{params.cpdName},'%')
    
    
        and  cpd.Pcs_Task_Name like concat('%',#{params.pcsTaskName},'%')
    
    
        and  pcs.Pcs_Create_Uname like concat('%',#{params.pcsCreateUname},'%')
    
    
        
            and Pcs_Actual_Start_Time is  null
        
    
    
        and  pcs.Pcs_Handler =#{params.pcsHandler}
    


    
        order by pcs.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by pcs.Pcs_Create_Time desc
